extern "C" __global__ void __launch_bounds__(128) stwo_composition_wave_9687aa7eae50ecaf(
    const StwoCudaCompositionWavePart *parts,
    const unsigned *random_coeff_powers,
    unsigned *coord_0,
    unsigned *coord_1,
    unsigned *coord_2,
