    wave_acc = stwo_qm31_add(wave_acc, stwo_composition_wave_part_5(
        parts[5u], random_coeff_powers, full_domain_rows, row_index));
    wave_acc = stwo_qm31_add(wave_acc, stwo_composition_wave_part_6(
